#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUTPUT_ROOT="$PROJECT_ROOT/.infinityfree-deploy"
DEPLOY_DIR="$OUTPUT_ROOT/package-$(date +%Y%m%d-%H%M%S)"
HTDOCS="$DEPLOY_DIR/htdocs"
ENV_FILE="$OUTPUT_ROOT/.deploy-state"
mkdir -p "$OUTPUT_ROOT"

banner "InfinityFree deployment"

stage "InfinityFree: Website und HTTPS"
open_url "https://dash.infinityfree.com/login"
step "Log in and select or create the hosting account and domain for this site."
step "Use an HTTPS address; InfinityFree free subdomains have HTTPS managed by the host."
ask APP_URL "Public website URL (for example https://verein.infinityfreeapp.com):"
APP_URL="${APP_URL%/}"
if [[ "$APP_URL" != https://* || "$APP_URL" == *[[:space:]]* ]]; then
  warn "APP_URL must be a public HTTPS URL without a trailing slash."
  return 1
fi
write_env APP_URL "$APP_URL"
ask APP_ENV "Application environment (local or production; use production for this host):"
if [[ "$APP_ENV" != local && "$APP_ENV" != production ]]; then
  warn "APP_ENV must be local or production."
  return 1
fi
write_env APP_ENV "$APP_ENV"

stage "InfinityFree: Leere MySQL-Datenbank"
open_url "https://dash.infinityfree.com/"
step "Open the hosting account's Control Panel, then MySQL Databases, and create a new empty database."
step "Copy the database hostname, database name and username shown under Current Databases."
step "Use the password required by the panel for this database. The database hostname is not localhost."
ask DB_HOST "MySQL hostname:"
ask DB_NAME "New database name:"
ask DB_USER "Database username:"
ask_secret DB_PASSWORD "Database password:"
ask DB_PORT "MySQL port (from the hosting provider):"
if [[ ! "$DB_PORT" =~ ^[0-9]{1,5}$ ]] || (( 10#$DB_PORT < 1 || 10#$DB_PORT > 65535 )); then
  warn "DB_PORT must be between 1 and 65535."
  return 1
fi
for key in DB_HOST DB_NAME DB_USER DB_PASSWORD; do
  if [[ -z "${!key}" ]]; then
    warn "$key must not be empty."
    return 1
  fi
done
write_env DB_HOST "$DB_HOST"
write_env DB_PORT "$DB_PORT"
write_env DB_NAME "$DB_NAME"
write_env DB_USER "$DB_USER"
write_env DB_PASSWORD "$DB_PASSWORD"

stage "E-Mail-Versand über PHP mail()"
step "Check that your hosting plan supports PHP mail() and permits the sender address."
note "SMTP credentials are no longer used by the application. If mail() is unavailable, invitations and password reset emails cannot be sent."
ask MAIL_FROM "Sender email address permitted by your host:"
ask MAIL_FROM_NAME "Sender display name:"
if [[ -z "$MAIL_FROM" || -z "$MAIL_FROM_NAME" ]]; then
  warn "Sender address and display name are required."
  return 1
fi
ask MAIL_REPLY_TO "Reply-To email address (optional; leave blank to use the sender address):"
write_env MAIL_REPLY_TO "$MAIL_REPLY_TO"
write_env MAIL_FROM "$MAIL_FROM"
write_env MAIL_FROM_NAME "$MAIL_FROM_NAME"

stage "InfinityFree: Uploadpaket lokal erstellen"
if [[ ! -f "$PROJECT_ROOT/node_modules/.bin/esbuild" ]]; then
  warn "Frontend build dependencies are missing. Run 'npm ci' in the project, then rerun this wizard."
  return 1
fi
(cd "$PROJECT_ROOT" && npm run build)
if [[ ! -f "$PROJECT_ROOT/www/vendor/autoload.php" ]]; then
  if ! command -v composer >/dev/null 2>&1; then
    warn "Composer dependencies are missing. Install them with Composer, then rerun this wizard."
    return 1
  fi
  (cd "$PROJECT_ROOT/www" && composer install --no-dev --no-interaction --prefer-dist --optimize-autoloader)
fi

mkdir -p "$HTDOCS" "$HTDOCS/config" "$HTDOCS/storage"
cp -a "$PROJECT_ROOT/www/assets" "$PROJECT_ROOT/www/app" "$PROJECT_ROOT/www/database" "$PROJECT_ROOT/www/vendor" "$HTDOCS/"
cp "$PROJECT_ROOT/www/index.php" "$PROJECT_ROOT/www/.htaccess" "$PROJECT_ROOT/www/composer.json" "$PROJECT_ROOT/www/composer.lock" "$HTDOCS/"
cp "$PROJECT_ROOT/www/config/.htaccess" "$HTDOCS/config/.htaccess"
cp "$PROJECT_ROOT/www/storage/.htaccess" "$HTDOCS/storage/.htaccess"
printf 'Require all denied\n' > "$HTDOCS/vendor/.htaccess"
cp "$ENV_FILE" "$HTDOCS/config/.env"
chmod 0600 "$HTDOCS/config/.env"
note "Package created at: $HTDOCS"
note "Private environment file created at: $HTDOCS/config/.env"

stage "InfinityFree: Dateien nach htdocs hochladen"
open_url "https://dash.infinityfree.com/"
step "In the account Control Panel, open FTP Details and connect with FileZilla."
step "Enter FTP credentials directly in FileZilla; they are not collected or saved by this wizard."
step "Upload the CONTENTS of this directory into htdocs: $HTDOCS"
step "Include hidden .htaccess files and keep app, config, database, vendor and assets/build as folders."
step "The active environment file is included at config/.env inside the package. Upload it with the other files."
warn "Do not upload $ENV_FILE; it contains only local deployment-wizard state."
warn "Uploading may replace files already present in htdocs."
confirm "Is this the intended new site, and may its htdocs files be replaced?" || return 1
pause "Press Enter after all package files have been uploaded"

stage "InfinityFree: Datenbankschema importieren"
open_url "https://dash.infinityfree.com/"
step "In MySQL Databases, open phpMyAdmin for the new database you just created."
step "Select Import and upload this file first: $HTDOCS/database/install.sql"
step "Repeat Import with this file: $HTDOCS/database/seed_resources.sql"
warn "Import only into the new empty database; do not import these files into an existing database."
confirm "Is the selected database the new empty database, and may these schema files be imported?" || return 1
pause "Press Enter after both SQL files have been imported"

stage "InfinityFree: Admin einrichten und prüfen"
open_url "$APP_URL/?page=setup"
step "Create the first administrator account; the setup does not require a separate key."
pause "Press Enter after the admin account has been created"
open_url "$APP_URL/"
if ! command -v curl >/dev/null 2>&1; then
  warn "curl is unavailable; verify the calendar manually at $APP_URL/"
else
  CHECK_FILE="$OUTPUT_ROOT/calendar-check.html"
  HTTP_STATUS="$(curl --location --silent --show-error --output "$CHECK_FILE" --write-out '%{http_code}' "$APP_URL/")" || {
    warn "Could not reach the deployed site. Check DNS, HTTPS and the uploaded files, then rerun the smoke check."
    return 1
  }
  if [[ "$HTTP_STATUS" != "200" ]] || ! grep -q 'class="calendar-navigation"' "$CHECK_FILE"; then
    warn "The calendar smoke check failed with HTTP $HTTP_STATUS."
    return 1
  fi
  rm -f "$CHECK_FILE"
  say "Calendar smoke check passed (HTTP 200)."
fi
say "Send a test invitation to an address you control and check its inbox and spam folder."
warn "PHP mail() must be enabled by your host. A successful handoff does not confirm delivery."
note "After successful verification, securely delete the local .infinityfree-deploy directory."

finish
}

run_wizard "$@"; exit
